// Three drum "feels" at the same tempo (110 BPM), two bars each:
// bars 1-2 four-on-the-floor (kick every beat: house, dance, momentum)
// bars 3-4 backbeat (kick on 1 and 3, snare on 2 and 4: pop, rock, the head-nod)
// bars 5-6 half-time (snare only on beat 3: trap, future bass, feels twice as slow and heavier)
setcpm(110/4)
// stem: drums
$: s("bd*4, ~ cp ~ cp, [~ oh]*4").gain(.6).mask("<1 1 0 0 0 0 0>")
// stem: drums
$: s("bd ~ bd ~, ~ sd ~ sd, hh*8").gain(.6).mask("<0 0 1 1 0 0 0>")
// stem: drums
$: s("bd ~ ~ ~ ~ ~ ~ ~ ~ ~ bd ~ ~ ~ ~ ~, ~ ~ sd ~, hh*8").gain(.6).mask("<0 0 0 0 1 1 0>")
// stem: bass
$: note("<a1 a1 f1 f1 g1 g1>").segment(8).s("triangle").lpf(500).decay(.2).sustain(.2).gain(.8).mask("<1 1 1 1 1 1 0>")
all(x => x.postgain(.75))

// Straight vs swung. Bars 1-2: every 16th note exactly on the grid (machine, precise, "tech").
// Bars 3-4: every second 16th pushed late (human, relaxed, groovy: lo-fi, garage, boom bap).
setcpm(92/4)
// stem: drums
$: s("hh*16").gain(".35 .15 .25 .15").mask("<1 1 0 0 0>")
// stem: drums
$: s("hh*16").gain(".35 .15 .25 .15").swingBy(1/3, 8).mask("<0 0 1 1 0>")
// stem: drums
$: s("bd ~ ~ ~ ~ ~ bd ~ bd ~ ~ ~ ~ ~ ~ ~, ~ sd ~ sd").gain(.65).mask("<1 1 1 1 0>")
all(x => x.postgain(.8))

// Syncopation. Bars 1-2: chord stabs land ON the beats (stiff, corporate).
// Bars 3-4: the same chords land BETWEEN the beats (funky, forward-leaning, alive).
setcpm(118/4)
const prog = "<Am7 D9>"
// stem: chords
$: chord(prog).voicing().struct("x ~ ~ ~ x ~ ~ ~ x ~ ~ ~ x ~ ~ ~").s("sawtooth").lpf(1800).decay(.2).sustain(0).gain(.3).mask("<1 1 0 0 0>")
// stem: chords
$: chord(prog).voicing().struct("~ ~ x ~ ~ x ~ ~ ~ ~ x ~ ~ x ~ x").s("sawtooth").lpf(1800).decay(.2).sustain(0).gain(.3).mask("<0 0 1 1 0>")
// stem: drums
$: s("bd*4, [~ hh]*4").gain(.55).mask("<1 1 1 1 0>")
all(x => x.postgain(.8))

// Major vs minor: the same melody and rhythm, only the scale changes.
// Bars 1-2 C major (bright, open, resolved). Bars 3-4 C minor (darker, serious, cool; not necessarily sad).
setcpm(100/4)
// stem: melody
$: n("[0 2 4 7 4 2 4 5]").scale("<C4:major C4:major C4:minor C4:minor>").s("triangle").decay(.25).sustain(0).gain(.8).room(.3).mask("<1 1 1 1 0>")
// stem: chords
$: n("[0,2,4]").scale("<C3:major C3:major C3:minor C3:minor>").s("sawtooth").lpf(1200).attack(.1).release(.5).gain(.15).mask("<1 1 1 1 0>")
// stem: bass
$: note("c2").s("sine").gain(.6).mask("<1 1 1 1 0>")
all(x => x.postgain(.8))

// Four modes, same root (C), same melody, two bars each. Listen for the one "flavour note".
// Lydian (bars 1-2): raised 4th, floating wonder, "the future is bright". Dorian (3-4): minor but hopeful, cool, smart.
// Phrygian (5-6): lowered 2nd, dark, menacing, security/hacker. Mixolydian (7-8): major with a flat 7th, confident swagger.
setcpm(100/4)
// stem: melody
$: n("<[0 1 2 3 4 5 6 7] [6 5 4 3 2 1 0 ~]>").scale("<C4:lydian!2 C4:dorian!2 C4:phrygian!2 C4:mixolydian!2>")
   .s("triangle").decay(.3).sustain(0).gain(.85).room(.3).mask("<1 1 1 1 1 1 1 1 0>")
// stem: bass
$: note("[c2,g2]").s("sawtooth").lpf(500).attack(.2).release(.5).gain(.3).mask("<1 1 1 1 1 1 1 1 0>")
all(x => x.postgain(.8))

// Chord colour, one bar each on the piano: plain C triad (simple), Cmaj7 (dreamy, sophisticated),
// Cmaj9 (lush, expensive), then Csus4 resolving to C (tension, then "home").
setcpm(72/4)
// stem: chords
$: chord("<C C^7 C^9 [Csus C]>").voicing().s("piano").gain(.6).room(.4).mask("<1 1 1 1 0>")
// stem: bass
$: note("c2").s("piano").gain(.5).mask("<1 1 1 1 0>")
all(x => x.postgain(.9))

// Same four chords, different "home". Bars 1-4: C G Am F (I-V-vi-IV: the pop anthem, uplifting, risks sounding generic).
// Bars 5-8: Am F C G (vi-IV-I-V / i-VI-III-VII: starts minor, bittersweet, cinematic, the EDM/trailer staple).
setcpm(96/4)
const prog = "<C G Am F Am F C G>"
// stem: melody
$: n("0 1 2 3 2 1 2 3").chord(prog).voicing().s("piano").gain(.5).room(.3).mask("<1 1 1 1 1 1 1 1 0>")
// stem: bass
$: chord(prog).rootNotes(2).s("piano").gain(.5).mask("<1 1 1 1 1 1 1 1 0>")
// stem: bass
$: note("c2").s("piano").gain(.55).mask("<0 0 0 0 0 0 0 0 1>")
// stem: chords
$: note("[e3,g3,c4]").s("piano").gain(.45).mask("<0 0 0 0 0 0 0 0 1>")
all(x => x.postgain(.9))

// The four raw synth waveforms playing the same riff, one bar each:
// sine (pure, soft, sub-bass), triangle (gentle, flute-like), square (hollow, retro 8-bit), sawtooth (bright, buzzy, the basis of most synth sounds).
setcpm(100/4)
// stem: melody
$: note("[c3 c3 eb3 g3 c4 g3 eb3 c3]").s("<sine triangle square sawtooth>").decay(.2).sustain(.3).release(.05).gain(.6).mask("<1 1 1 1 0>")
all(x => x.postgain(.8))

// Filter sweep: the most universal "build" gesture. A low-pass filter opens over 4 bars
// (muffled, distant, "next room" -> bright, present, "here it is"), then snaps shut.
setcpm(120/4)
// stem: chords
$: chord("<Am9 Am9 F^9 G6 Am9>").voicing().struct("x*8").s("sawtooth")
   .lpf("<[200 400] [600 900] [1300 2000] [3000 5000] 400>").lpq(6).decay(.15).sustain(.3).gain(.3).mask("<1 1 1 1 1 0>")
// stem: drums
$: s("bd*4").gain(.6).mask("<1 1 1 1 1 0>")
all(x => x.postgain(.8))

