$: note("<[a3,c4,e4,g4] [g3,b3,d4,e4]>").s("sawtooth").lpf(1300).attack(.4).release(1.2)
   .gain(.12).room(.6).size(4).mask(padOn).orbit(2)
// button: resolve on F with piano + sub on the end card
// stem: chords
$: note("[f1,f2,c3,a3,e4,g4]").s("piano").gain(.6).room(.5).mask(buttonOn)
// stem: bass
$: note("f1").s("sine").decay(1.5).sustain(0).gain(.8).mask(buttonOn)
all(x => x.postgain(.8))

